// Append A to new parent on left.
folderDB.moveFolderTo(left, a);
drawTree(grandparent);
Assert.equal(folderDB.getFolderParent(a), left);
Assert.deepEqual(folderDB.getFolderChildren(left), [a]);
Assert.deepEqual(folderDB.getFolderChildren(parent), [b, c, d]);
checkOrdinals([
  [left, grandparent, null],
  [a, left, null],
  [parent, grandparent, null],
  // No need to change the existing ordinals on remaining children,
  // the order remains the same.
  [b, parent, 2],
  [c, parent, 3],
  [d, parent, 4],
]);

function checkOrdinals(expected) {
  const stmt = database.connectionForTests.createStatement(
    "SELECT parent, ordinal FROM folders WHERE id=:id"
  );
  for (const [folder, parent, ordinal] of expected) {
    stmt.params.id = folder;
    stmt.executeStep();
    Assert.deepEqual(
      [stmt.row.parent, stmt.row.ordinal],
      [parent, ordinal],
      `parent and ordinal of '${folderDB.getFolderName(folder)}'`
    );
    stmt.reset();
  }
  stmt.finalize();
}

